INSERT INTO `soal` VALUES ('345','8','25','<p>Diketahui persamaan lingkaran <img src=\"data:image/png;base64,\" /></p>\r\n<p>Diantara empat penyataan berikut, tentukan pernyataan yang benar!</p>\r\n<ol>\r\n<li>Lingkaran tersebut berpusat di (3, 1)</li>\r\n<li>Panjang jari-jari lingkaran tersebut 6 satuan panjang</li>\r\n<li>Jarak pusat lingkaran dengan sumbu x adalah 3</li>\r\n<li>Jarak pusat lingkaran dengan sumbu y adalah 1</li>\r\n</ol>','1','Pernyataan 1 dan 2 ','Pernyataan 1 dan 3','Pernyataan 1 dan 4','Pernyataan 3 dan 4','Pernyataan 2 dan 3','A','','','','','','','');
