INSERT INTO `soal` VALUES ('520','33','40','Apakah pembuat keputusan benar-benar mempertimbangkan segala aspek dalam proses pemilihan media promosi, merupakan jenis kriteria yang digunakan untuk pengambil keputusan yaitu&hellip;','1','Optimistic','Practicality','Throughness','Progressiveness','Measure-Mindedness','E',NULL,'','','','','','');
