INSERT INTO `soal` VALUES ('1033','5','33','<p><strong>Bacalah kutipan puisi berikut!</strong></p>\r\n<p>Matahari menyapa dedaunan dengan lembut</p>\r\n<p>Membangunkan embun dari tidur panjangnya</p>\r\n<p>Burung-burung bernyanyi riang menyambut pagi</p>\r\n<p>&nbsp;</p>\r\n<p>Majas yang paling dominan digunakan dalam penggalan puisi di atas adalah...</p>','1','<p>Metafora</p>','<p>Hiperbola</p>','<p>Simile</p>','<p>Ironi</p>','<p>Personifikasi</p>','E','','','','','','','');
