INSERT INTO `soal` VALUES ('1035','5','35','<p>Bacalaj penggalan puisi berikut!</p>\r\n<p>Di hitam matamu kemang mawar dan melati</p>\r\n<p>Harum rambutnya mengalun bergelut senda</p>\r\n<p>Sepi menyanyi malam dalam mendoa tiba</p>\r\n<p>Meriak muka air kolam jiwa</p>\r\n<p>&nbsp;</p>\r\n<p>Penggalan puisi diatas menggambarkan suasa...</p>','1','<p>Malam yang sepi dan menatkan sehingga orang-orang berdoa</p>','<p>Malam yang sepi di tepi kolam yang menakutkan orang di sekelilingnya</p>','<p>Tenang dan khusuk pada malam hari di tepi kolam yang airnya beriak-riak</p>','<p>Malam yang sunyi tapi indah dan mendebarkan saat memandang kekasihnya</p>','<p>Sepi yang mencekam di tepi kolam yang erombak-ombak pada malam hari</p>','D','','','','','','','');
INSERT INTO `soal` VALUES ('1036','5','36','<p>Bacalah kutipan puisi berikut!</p>\r\n<p><em>Kupandangi sekolahku yang indah menawan</em></p>\r\n<p><em>Lama kupandangi tak terasa</em></p>\r\n<p><em>Di sini aku belajar, di sini aku mendapat ilmu</em></p>\r\n<p><em>Banyak guru yang bermutu, memberi ilmu untuk bekal nanti</em></p>\r\n<p><em>Terima kasih sekolahku nan indah&nbsp;</em></p>\r\n<p>&nbsp;</p>\r\n<p>Tema yang tepat untuk puisi di atas adalah...</p>','1','<p>Cita-cita</p>','<p>Lingkungan</p>','<p>Persahabatan</p>','<p>Keindahan alam</p>','<p>Pendidikan</p>','E','','','','','','','');
