INSERT INTO `soal` VALUES ('1039','5','39','<p>Cermati larik puisi berikut!</p>\r\n<p><em>Air mata mengalir membasahi pipi, deras bagai air bah</em></p>\r\n<p>&nbsp;</p>\r\n<p>Majas yang dominan dalam larik puisi tersebut adalah majas...</p>','1','<p>Simile</p>','<p>Metafora</p>','<p>Personifikasi</p>','<p>Hiperbola</p>','<p>Ironi</p>','A','','','','','','','');
INSERT INTO `soal` VALUES ('1040','5','40','<p>Bacalah puisi berikut!</p>\r\n<p>Nanti, nantikanlah</p>\r\n<p>Rumput kering kemuning terhampar luas</p>\r\n<p>Gemetar tampak hawa panas atas padang rumput sunyi</p>\r\n<p>Ah, rumput, akarmu jangan turut mengering</p>\r\n<p>Jangan mati kaku di tanah terbaringNanti, nantikanlah dengan sabar dan tabah</p>\r\n<p>Sampai hujan turun membasahi bumi</p>\r\n<p>&nbsp;</p>\r\n<p>Rumput kering pada puisi di atas adalah simbol dari...</p>','1','<p>Rumput kekurangan air</p>','<p>Rumput di musim kemarau</p>','<p>Anak-anak gembala di padang rumput</p>','<p>Rakyat indonesia yang menderita</p>','<p>Ternak yang kurus kurang makan</p>','D','','','','','','','');
