INSERT INTO `soal` VALUES ('1074','2','36','Ajaran Islam bukan hanya mementingkan soal akhirat tetapi juga soal dunia. Umat Islam juga harus memperhatikan kehidupan dunia. Pemikiran ini dikemukakan oleh &hellip;.','1','Jamaludin al Afghani','Muhammad Rasyid Ridha','Muhammad Abduh','Sultan Mahmud II','Rifa&rsquo;ah Baidawi R. al-Tahtawi','A',NULL,'','','','','','');
