INSERT INTO `soal` VALUES ('1589','35','29','Apa yang dimaksud dengan &quot;sponsorship&quot; dalam dunia konten kreator?','1','Proses menghasilkan konten yang menyebalkan.','Keterlibatan dalam persaingan dengan konten kreator lain','Kerja sama dengan merek atau perusahaan yang membayar konten kreator untuk mempromosikan produk atau layanan mereka.','Mengubah niche konten secara drastis.','Penghasil cuan','C',NULL,'','','','','','');
