INSERT INTO `soal` VALUES ('1610','24','10','Seorang pemimpin perusahaan harus bisa memimpin dan membuat strategi untuk kemajuan usahanya, apabila ada masalah dalam perusahaan yang dipimpin, tindakan yang harus ia lakukan adalah...','1','Mengubah struktur organisasi ','Berdiskusi dengan karyawan untuk mencari solusi terbaik ','Mendelegasikan wewenang kepada bawahan ','Memberikan hukuman kepada pihak yang memicu permasalahan ','Belajar menangani masalah dari perusahaan lain.','B',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('1611','24','11','Lokasi kerja yang bersih dapat menunjang kualitas makanan yang dihasilkan. Salah satu syarat lantai lokasi kerja yang bersih adalah... ','1','Tahan air dan berwarna terang ','Memiliki ventilasi untuk sirkulasi ','Tahan air dan mudah dibersihkan ','Permukaan harus rata dan kedap air ','Cahaya terang untuk proses produksi ','D',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('1612','24','12','Alasan memilih bahan lap yang lembut dalam membersihkan debu yang menempel pada lokasi kerja adalah...  ','1','Menghindari lecetnya suatu benda ','Tidak ada makanan yang menempel ','Terhindar dari kerusakan peralatan ','Tahan air dan mudah dibersihkan ','Mudah dibawa dan dipegang ','A',NULL,'','','','','','');
INSERT INTO `soal` VALUES ('1613','24','13','Bahaya biologis dapat berasal dari banyak faktor berikut yan tidak termasuk sumber bahaya biologis dalam makanan adalah...','1','Bahan baku ','Hama ','karyawan','Listrik ','Peralatan','D',NULL,'','','','','','');
