INSERT INTO `soal` VALUES ('1639','24','39','Hidangan pembuka panas (hot appitezer) memiliki bentuk yang kecil, gurih, dan asin. Struktur hidangan ini tepat jika disajikan dalam keadaan panas, serta tidak mengenyangkan. Contoh hidangan yang dimaksud adalah...','1','Salad buah , salad sayur, roti ','Salad sayur, risoles, croquette','Roti bakar, salad buah, sup','Salad sayur, kue, galatin','Croquette, risoles, galatin','E',NULL,'','','','','','');
